Arguments: {"cwd":null,"title":"Inspect free dyslexia spelling worksheet section","code":"const tabId = 103795237;
const freeSection = await browserjs(tabId, () => {
  const h2 = Array.from(document.querySelectorAll('h2')).find(el => el.textContent.includes('Free Dyslexia Spelling Worksheet'));
  if (!h2) return null;
  let p = h2.nextElementSibling;
  let text = "";
  for (let i = 0; i < 5 && p; i++) {
    text += p.outerHTML + "\n";
    p = p.nextElementSibling;
  }
  return text;
});
console.log("Free section:", freeSection);
"}
